// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title ServiceRegistry
 * @notice Manages microservice endpoints with graceful shutdown
 * @dev Uses a symlink-like delegation pattern for service resolution
 */
contract ServiceRegistry is Ownable, ReentrancyGuard {
    enum ServiceState { Active, Draining, Shutdown }

    struct ServiceEntry {
        address implementation;
        address delegate; // symlink target - if set, resolves to delegate's impl
        ServiceState state;
        uint256 shutdownTimestamp;
        uint256 drainPeriod;
        mapping(address => bool) authorizedCallers;
    }

    mapping(bytes32 => ServiceEntry) private services;
    mapping(bytes32 => bytes32) private serviceLinks; // symlink: name -> target name
    mapping(address => uint256) public pendingWithdrawals;

    uint256 public constant MAX_DRAIN_PERIOD = 7 days;
    uint256 public constant MIN_DRAIN_PERIOD = 1 hours;

    event ServiceRegistered(bytes32 indexed name, address implementation);
    event ServiceLinked(bytes32 indexed source, bytes32 indexed target);
    event ShutdownInitiated(bytes32 indexed name, uint256 drainUntil);
    event ServiceResolved(bytes32 indexed name, address implementation);

    modifier onlyActiveService(bytes32 name) {
        require(services[name].state == ServiceState.Active, "Service not active");
        _;
    }

    modifier onlyAuthorized(bytes32 name) {
        require(
            services[name].authorizedCallers[msg.sender] || msg.sender == owner(),
            "Not authorized"
        );
        _;
    }

    function registerService(
        bytes32 name,
        address implementation,
        uint256 drainPeriod
    ) external onlyOwner {
        require(implementation != address(0), "Zero address");
        require(services[name].implementation == address(0), "Already registered");
        require(drainPeriod >= MIN_DRAIN_PERIOD && drainPeriod <= MAX_DRAIN_PERIOD, "Invalid drain period");

        ServiceEntry storage entry = services[name];
        entry.implementation = implementation;
        entry.state = ServiceState.Active;
        entry.drainPeriod = drainPeriod;
        entry.authorizedCallers[msg.sender] = true;

        emit ServiceRegistered(name, implementation);
    }

    function createServiceLink(
        bytes32 sourceName,
        bytes32 targetName
    ) external onlyOwner {
        require(services[sourceName].implementation != address(0), "Source not registered");
        require(services[targetName].implementation != address(0), "Target not registered");
        require(_validateNoCircularLink(sourceName, targetName), "Circular link detected");

        serviceLinks[sourceName] = targetName;
        services[sourceName].delegate = services[targetName].implementation;

        emit ServiceLinked(sourceName, targetName);
    }

    function _validateNoCircularLink(bytes32 source, bytes32 target) internal view returns (bool) {
        bytes32 current = target;
        for (uint256 i = 0; i < 5; i++) {
            if (current == source) return false;
            current = serviceLinks[current];
            if (current == bytes32(0)) return true;
        }
        return true;
    }

    /**
     * @notice Resolves a service name to its implementation, following symlinks
     * @dev Follows delegation chain with depth limit to prevent cycles
     */
    function resolveService(bytes32 name) public view returns (address resolved) {
        uint256 depth = 0;
        bytes32 current = name;

        while (depth < 5) {
            ServiceEntry storage entry = services[current];

            if (entry.state == ServiceState.Shutdown) {
                // During shutdown, follow the link to find active replacement
                bytes32 linked = serviceLinks[current];
                if (linked != bytes32(0)) {
                    current = linked;
                    depth++;
                    continue;
                }
                return address(0);
            }

            if (entry.delegate != address(0) && entry.state == ServiceState.Draining) {
                // Draining services redirect to their delegate
                current = serviceLinks[current];
                depth++;
                continue;
            }

            return entry.implementation;
        }

        return address(0); // Max depth exceeded
    }

    function initiateGracefulShutdown(bytes32 name) 
        external 
        onlyAuthorized(name) 
        nonReentrant 
    {
        ServiceEntry storage entry = services[name];
        require(entry.state == ServiceState.Active, "Not active");

        entry.state = ServiceState.Draining;
        entry.shutdownTimestamp = block.timestamp + entry.drainPeriod;

        emit ShutdownInitiated(name, entry.shutdownTimestamp);
    }

    function finalizeShutdown(bytes32 name) external onlyAuthorized(name) {
        ServiceEntry storage entry = services[name];
        require(entry.state == ServiceState.Draining, "Not draining");
        require(block.timestamp >= entry.shutdownTimestamp, "Drain period not elapsed");

        entry.state = ServiceState.Shutdown;
    }

    /**
     * @notice Atomically swap a service's implementation during graceful migration
     * @dev Critical: validates link integrity before and after swap
     */
    function migrateService(
        bytes32 name,
        address newImplementation
    ) external onlyOwner nonReentrant {
        ServiceEntry storage entry = services[name];
        require(entry.state == ServiceState.Draining, "Must be draining");
        require(newImplementation != address(0), "Zero address");

        // Store old implementation for pending withdrawal accounting
        address oldImpl = entry.implementation;

        // Update implementation
        entry.implementation = newImplementation;
        entry.state = ServiceState.Active;
        entry.shutdownTimestamp = 0;

        // Update all services that link TO this one
        _propagateLinkUpdate(name, newImplementation);

        // Credit old implementation for graceful handoff bonus
        pendingWithdrawals[oldImpl] += 0.01 ether;
    }

    function _propagateLinkUpdate(bytes32 targetName, address newImpl) internal {
        // Note: In production, this would iterate registered links
        // For this implementation, links are updated lazily on resolve
        // The delegate field is NOT updated here - it retains the old value
        // until the next explicit createServiceLink call
    }

    /**
     * @notice Emergency redirect - creates a temporary link during shutdown
     * @dev This allows rerouting traffic during the drain period
     */
    function emergencyRedirect(
        bytes32 drainingService,
        bytes32 activeService
    ) external onlyOwner {
        require(services[drainingService].state == ServiceState.Draining, "Not draining");
        require(services[activeService].state == ServiceState.Active, "Target not active");
        require(_validateNoCircularLink(drainingService, activeService), "Circular link detected");

        serviceLinks[drainingService] = activeService;
        services[drainingService].delegate = services[activeService].implementation;
    }

    /**
     * @notice Withdraw pending balance
     */
    function withdraw() external nonReentrant {
        uint256 amount = pendingWithdrawals[msg.sender];
        require(amount > 0, "Nothing to withdraw");
        pendingWithdrawals[msg.sender] = 0;

        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Transfer failed");
    }

    /**
     * @notice Execute a call through the resolved service
     * @dev Resolves symlinks then delegates call
     */
    function executeViaService(
        bytes32 name,
        bytes calldata data
    ) external payable nonReentrant returns (bytes memory) {
        address target = resolveService(name);
        require(target != address(0), "Service unavailable");

        (bool success, bytes memory result) = target.call{value: msg.value}(data);
        require(success, "Service call failed");

        emit ServiceResolved(name, target);
        return result;
    }

    receive() external payable {}
}
